// AppVersion.swift — the version string the About panel shows.
//
// WHY THIS IS A FUNCTION AND NOT AN INLINE `?? "1.0"`
// The fallback is the part that matters, and an inline expression is exactly the
// kind that gets tidied into `Bundle.main.infoDictionary?[...] as! String`. Two
// real cases make the fallback necessary: a `swift run` build has no Info.plist
// at all, and a packaged build can carry an empty or whitespace-only value when
// the plist is generated by a script. Both must render "1.0", not a dash and not
// a crash. Keeping it here means a test can state that.

public enum AppVersion {

    /// Shown when the bundle cannot answer. Matches the first release, which is
    /// the least surprising thing to display for a build with no plist.
    public static let fallback = "1.0"

    /// `CFBundleShortVersionString` from an Info.plist dictionary, or `fallback`
    /// when the key is missing, is not a string, or is blank.
    public static func short(from info: [String: Any]?) -> String {
        guard let raw = info?["CFBundleShortVersionString"] as? String else {
            return fallback
        }
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? fallback : trimmed
    }
}
